// trigger notifies all listeners that the data has changed
func (s *sprintf) trigger() {
	s.lock.RLock()
	items := make([]DataListener, len(s.listeners))
	copy(items, s.listeners)
	s.lock.RUnlock()

	for _, item := range items {
		queueItem(item.DataChanged)
	}
}

// StringToStringWithFormat creates a string binding that reformats another string binding.
// This is a convenience wrapper around NewSprintf for the common case of formatting a single string.
//
// Since: 2.2
func StringToStringWithFormat(source String, format string) String {
	return NewSprintf(format, source)
}
