// parseColor converts a hex color string to a color.Color
// Supports: 3, 4, 6, 8 digit hex, with or without # prefix
// Examples: "F00", "#FF0000", "FF0000AA", "#RGBA"
func parseColor(s string) (color.Color, error) {
	if len(s) == 0 {
		return nil, errors.New("empty color string")
	}

	// Strip # prefix if present
	if s[0] == '#' {
		s = s[1:]
	}

	var r, g, b, a byte
	a = 255 // Default alpha

	switch len(s) {
	case 3: // RGB
		r = hexDigitToByte(s[0])
		r = r*16 + r
		g = hexDigitToByte(s[1])
		g = g*16 + g
		b = hexDigitToByte(s[2])
		b = b*16 + b

	case 4: // RGBA
		r = hexDigitToByte(s[0])
		r = r*16 + r
		g = hexDigitToByte(s[1])
		g = g*16 + g
		b = hexDigitToByte(s[2])
		b = b*16 + b
		a = hexDigitToByte(s[3])
		a = a*16 + a

	case 6: // RRGGBB
		var err error
		if r, err = hexByteToByte(s[0:2]); err != nil {
			return nil, err
		}
		if g, err = hexByteToByte(s[2:4]); err != nil {
			return nil, err
		}
		if b, err = hexByteToByte(s[4:6]); err != nil {
			return nil, err
		}

	case 8: // RRGGBBAA
		var err error
		if r, err = hexByteToByte(s[0:2]); err != nil {
			return nil, err
		}
		if g, err = hexByteToByte(s[2:4]); err != nil {
			return nil, err
		}
		if b, err = hexByteToByte(s[4:6]); err != nil {
			return nil, err
		}
		if a, err = hexByteToByte(s[6:8]); err != nil {
			return nil, err
		}

	default:
		return nil, errors.New("invalid hex color length")
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// hexDigitToByte converts a single hex digit to byte value
func hexDigitToByte(c byte) byte {
	switch {
	case c >= '0' && c <= '9':
		return c - '0'
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10
	case c >= 'A' && c <= 'F':
		return c - 'A' + 10
	default:
		return 0
	}
}

// hexByteToByte converts two hex digits to byte value
func hexByteToByte(s string) (byte, error) {
	if len(s) != 2 {
		return 0, errors.New("invalid hex byte")
	}
	hi := hexDigitToByte(s[0])
	lo := hexDigitToByte(s[1])
	return hi*16 + lo, nil
}

