	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		if source == nil {
			return fmt.Errorf("source at index %d is nil", i)
		}

		switch source.(type) {
		case String:
			var v string
			values[i] = &v
		case Int:
			var v int
			values[i] = &v
		case Float:
			var v float64
			values[i] = &v
		case Bool:
			var v bool
			values[i] = &v
		case URI:
			var v string
			values[i] = &v
		case Untyped:
			var v interface{}
			values[i] = &v
