{"path": "task/workspace/menu.go", "start": 1, "lines": 40, "offset": 0, "total_lines": 106, "content": "package fyne

// Menu stores the information required for a standard menu.
// A menu can pop down from a MainMenu or could be a pop out menu.
type Menu struct {
	Label string
	Items []*MenuItem
}

// NewMenu creates a new menu given the specified label (to show in a MainMenu) and list of items to display.
func NewMenu(label string, items ...*MenuItem) *Menu {
	return &Menu{Label: label, Items: items}
}

// Refresh causes this menu to update and redraw in all windows where it is currently displayed.
// This allows runtime changes to menu items (including icons and shortcuts) to be reflected.
//
// Since: 2.2
func (m *Menu) Refresh() {
	app := CurrentApp()
	if app == nil {
		return
	}

	// Refresh all windows that might be using this menu
	for _, window := range app.Driver().AllWindows() {
		if window.MainMenu() != nil {
			for _, menu := range window.MainMenu().Items {
				if menu == m {
					window.SetMainMenu(window.MainMenu())
					break
				}
			}
		}
