// Refresh causes this main menu to update and redraw in all windows where it is currently set.
// This allows runtime changes to the menu structure to be reflected.
//
// Since: 2.2
func (m *MainMenu) Refresh() {
	app := CurrentApp()
	if app == nil {
		return
	}

	// Refresh all windows using this main menu
	for _, window := range app.Driver().AllWindows() {
		if window.MainMenu() == m {
			window.SetMainMenu(m)
		}
	}
}
